INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Darstellungsschicht Teil des OSI-Modells?', 2, '[{"text": "Ja", "correct": true, "because": "Schicht 6"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Darstellungsschicht?', 3, '[{"text": "Datenformatierung und Darstellung", "correct": true, "because": "Sichert Verständnis"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1 Aufgabe"}, {"text": "Netzwerkadressen zuweisen", "correct": false, "because": "Schicht 3 Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Darstellungsschicht konvertiert Datenformate. b) Sie routet Datenpakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 3"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zur Darstellungsschicht?', 4, '[{"text": "Datenkompression", "correct": true, "because": "Reduziert Größe"}, {"text": "Unklare Übertragung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Verschlüsselung", "correct": true, "because": "Sichert Daten"}, {"text": "Datenformatkonvertierung", "correct": true, "because": "Passt Formate an"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne Darstellungsschicht funktionieren?', 2, '[{"text": "Ja", "correct": true, "because": "Grundfunktion möglich"}, {"text": "Nein", "correct": false, "because": "Kompatibilität leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Darstellungsschicht?', 3, '[{"text": "Daten für Anwendungen lesbar machen", "correct": true, "because": "Formatierung"}, {"text": "Daten physisch übertragen", "correct": false, "because": "Schicht 1 Aufgabe"}, {"text": "Netzwerkadressen verwalten", "correct": false, "because": "Schicht 3 Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Darstellungsschicht nur für technische Daten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Datenarten"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Verschlüsselung auf der Darstellungsschicht?', 3, '[{"text": "Datensicherheit gewährleisten", "correct": true, "because": "Schützt Daten"}, {"text": "Datenpakete routen", "correct": false, "because": "Schicht 3 Aufgabe"}, {"text": "Physische Verbindung", "correct": false, "because": "Schicht 1 Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Darstellungsschicht behandelt Datenkompression. b) Sie ist für Hardware zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Darstellungsschicht?', 3, '[{"text": "Datenformate sind inkompatibel", "correct": true, "because": "Keine Konvertierung"}, {"text": "Datenübertragung schneller", "correct": false, "because": "Eher Probleme"}, {"text": "Netzwerk funktioniert nicht", "correct": false, "because": "Andere Schichten aktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Darstellungsschicht ohne Anwendungsschicht arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängige Funktion"}, {"text": "Nein", "correct": false, "because": "Zusammenarbeit möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Funktion der Darstellungsschicht?', 3, '[{"text": "Daten mit SSL verschlüsseln", "correct": true, "because": "Konkret und real"}, {"text": "Datenpakete routen", "correct": false, "because": "Schicht 3 Aufgabe"}, {"text": "Irgendwas übertragen", "correct": false, "because": "Zu vage"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Darstellungsschicht nur für Textdaten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Datenformate"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Darstellungsschicht?', 4, '[{"text": "Datenkonvertierung", "correct": true, "because": "Passt Formate an"}, {"text": "Unklare Daten", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Kompression", "correct": true, "because": "Reduziert Datenmenge"}, {"text": "Verschlüsselung", "correct": true, "because": "Sichert Übertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Darstellungsschicht mit der Sitzungsschicht interagieren?', 2, '[{"text": "Ja", "correct": true, "because": "Datenfluss zwischen Schichten"}, {"text": "Nein", "correct": false, "because": "Interaktion üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll arbeitet typischerweise auf der Darstellungsschicht?', 3, '[{"text": "SSL/TLS", "correct": true, "because": "Verschlüsselt Daten"}, {"text": "IP", "correct": false, "because": "Schicht 3 Protokoll"}, {"text": "Ethernet", "correct": false, "because": "Schicht 2 Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Darstellungsschicht ohne Verschlüsselung arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Darstellungsschicht?', 3, '[{"text": "Datenformat des Kunden", "correct": true, "because": "Bestimmt Konvertierung"}, {"text": "Kabellänge", "correct": false, "because": "Schicht 1 Faktor"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Schicht 2/3 Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Darstellungsschicht behandelt JPEG. b) Sie überträgt Daten physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Schicht 1"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Darstellungsschicht?', 3, '[{"text": "Datenkompatibilität sicherstellen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Datenformatierung", "correct": false, "because": "Fördert Anpassung"}]');
